using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/admin/users")][Authorize(Policy=PermissionPolicies.UsersView)]public sealed class UsersAdminController(IUserAdminService s):ControllerBase{[HttpGet]public async Task<ActionResult<PagedResponse<UserAdminDto>>>Get([FromQuery]UserAdminQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct));[HttpPut("{id:long}")][Authorize(Policy=PermissionPolicies.UsersEdit)]public async Task<IActionResult>Update(long id,UpdateUserAdminRequest r,CancellationToken ct)=>await s.UpdateAsync(id,r,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct)?NoContent():Conflict();}}

